package dev.kubejseditor;

import com.google.gson.*;
import dev.kubejseditor.recipe.*;
import dev.kubejseditor.recipe.compat.*;
import dev.kubejseditor.model.RegistryEntryTarget;
import java.util.*;

public final class GenericPatchVerification {
    private static int checks;
    private static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
    private static JsonArray ops(String text){return JsonParser.parseString(text).getAsJsonArray();}
    private static void fails(Runnable call,String reason){checks++;try{call.run();}catch(RuntimeException expected){return;}throw new AssertionError(reason);}
    public record Box(Object payload){}
    public record Nested(Optional<Box> envelope){}
    public static final class Cycle {public Object getDelegate(){return this;}public Object getRecipe(){throw new IllegalStateException("unavailable optional wrapper");}}
    public static final class Accessor {private final Object actual;public Accessor(Object value){actual=value;}public Object getRecipe(){return actual;}}
    public static int run(){
        var base=RecipeAdapters.parse("{type:'example:process',inputs:[{ingredient:{item:'minecraft:iron_ingot'},amount:20480},{item:'minecraft:gold_ingot'}],output:{id:'minecraft:paper',components:{'minecraft:custom_data':{'a/b~c':7}}},settings:{chance:0.5,enabled:true},nullable:null}");var original=base.deepCopy();
        var changed=JsonPatches.apply(base,ops("[{op:'test',path:'/settings/chance',value:0.5},{op:'replace',path:'/settings/chance',value:0.75},{op:'replace',path:'/inputs/0/ingredient/item',value:'minecraft:copper_ingot'}]"));check(changed.getAsJsonObject("settings").get("chance").getAsDouble()==0.75,"Decimal values retain their native type");check(base.equals(original),"Preview never mutates the original recipe");check(JsonPatches.read(changed,"/inputs/0/amount").getAsInt()==20480,"Item identity replacement preserves independent large quantities");check(JsonPatches.read(changed,"/output/components/minecraft:custom_data/a~1b~0c").getAsInt()==7,"Escaped pointers preserve and address component contents");
        var inserted=JsonPatches.apply(base,ops("[{op:'add',path:'/inputs/1',value:{item:'minecraft:diamond'}},{op:'add',path:'/inputs/-',value:{item:'minecraft:emerald'}},{op:'remove',path:'/inputs/0'}]"));check(inserted.getAsJsonArray("inputs").size()==3&&JsonPatches.read(inserted,"/inputs/0/item").getAsString().equals("minecraft:diamond"),"Array insert, append and removal use stable sequential indices");
        var copied=JsonPatches.apply(base,ops("[{op:'copy',from:'/inputs/0',path:'/inputs/-'},{op:'replace',path:'/inputs/2/amount',value:99}]"));check(JsonPatches.read(copied,"/inputs/0/amount").getAsInt()==20480&&JsonPatches.read(copied,"/inputs/2/amount").getAsInt()==99,"Copied entries do not alias the original object");
        var moved=JsonPatches.apply(base,ops("[{op:'move',from:'/inputs/0',path:'/inputs/1'}]"));check(JsonPatches.read(moved,"/inputs/1/amount").getAsInt()==20480,"Moving list entries uses the post-removal array index");
        check(JsonPatches.read(base,"/nullable").isJsonNull(),"Present null fields remain distinguishable from missing paths");check(JsonPatches.fields(base).stream().anyMatch(f->f.path().contains("components")),"Raw field browsing includes opaque component payloads");
        var replacement=JsonPatches.replaceValues(base,"/inputs",new JsonPrimitive("minecraft:iron_ingot"),new JsonPrimitive("minecraft:copper_ingot"));check(replacement.size()==1&&JsonPatches.apply(base,replacement).getAsJsonArray("inputs").size()==2,"Scoped identity replacement generates exact path operations without changing list structure");check(JsonPatches.replaceValues(base,"/output",new JsonPrimitive("minecraft:iron_ingot"),new JsonPrimitive("minecraft:copper_ingot")).isEmpty(),"Batch replacement respects the chosen subtree");check(JsonPatches.replaceValues(base,"",new JsonPrimitive("example:process"),new JsonPrimitive("example:other")).isEmpty(),"Batch replacement excludes the recipe dispatch type");
        fails(()->JsonPatches.apply(base,ops("[{op:'replace',path:'/settings/chance',value:0.9},{op:'test',path:'/settings/enabled',value:false}]")),"Failed original-value test rejects the whole patch");check(base.equals(original),"Failure after an earlier operation leaves the source intact");
        fails(()->JsonPatches.apply(base,ops("[{op:'replace',path:'/missing',value:1}]")),"Replace cannot silently create a missing field");fails(()->JsonPatches.apply(base,ops("[{op:'replace',path:'/type',value:'example:other'}]")),"Type replacement is not a field patch");fails(()->JsonPatches.apply(base,ops("[{op:'remove',path:'/type'}]")),"Type deletion is rejected");fails(()->JsonPatches.read(base,"/inputs/01"),"Noncanonical array indices are rejected");fails(()->JsonPatches.read(base,"/inputs/-1"),"Negative array indices are rejected");fails(()->JsonPatches.read(base,"/inputs/99"),"Out-of-range access is rejected");fails(()->JsonPatches.read(base,"/inputs~2"),"Invalid JSON-pointer escapes are rejected");fails(()->JsonPatches.apply(base,ops("[{op:'move',from:'/settings',path:'/settings/self'}]")),"Moving into a descendant is rejected");fails(()->JsonPatches.apply(base,ops("[{op:'unknown',path:'/settings',value:1}]")),"Unknown operations are rejected");
        var many=new JsonArray();for(int i=0;i<513;i++)many.add(JsonPatches.operation("test","/nullable",JsonNull.INSTANCE));fails(()->JsonPatches.apply(base,many),"Oversized operation lists are bounded");
        var nativeObject=new Object();var graph=PublicObjectGraph.scan(new Nested(Optional.of(new Box(new Accessor(nativeObject)))),t->false);check(graph.stream().anyMatch(v->v==nativeObject),"Nested records, Optional and public Object-typed accessors unwrap without a mod name");check(PublicObjectGraph.scan(new Cycle(),t->false).size()==1,"Cycles and failing accessors cannot break other discovery");var wrapped=PublicObjectGraph.scan(Map.of("program",List.of(new Box(nativeObject))),t->false);check(wrapped.stream().anyMatch(v->v==nativeObject),"Map and list wrappers are traversed");Object deep=nativeObject;for(int i=0;i<20;i++)deep=new Box(deep);check(PublicObjectGraph.scan(deep,t->false).stream().noneMatch(v->v==nativeObject),"Wrapper traversal is depth bounded");
        check(AdaptationQuality.score(3,3,5,0,0,0,10)>AdaptationQuality.score(1,3,5,0,0,0,40),"Actual slot coverage outranks a profile name or priority");check(AdaptationQuality.score(3,3,5,0,0,0,10)>AdaptationQuality.score(3,3,5,2,0,1,40),"Unresolved fields and validation failures reduce preference");check(AdaptationQuality.score(0,0,4,0,2,0,10)>0,"A field-only page can still select a useful editing method");
        check(new RegistryEntryTarget("minecraft:enchantment","pack:example").path().contains("/pack/enchantment/example.json"),"Vanilla registry data folders omit the minecraft namespace prefix");var target=new RegistryEntryTarget("example:program","pack:example");check(target.path().contains("/pack/example/program/example.json"),"Custom data registry folders retain their namespace");
        return checks;
    }
    private GenericPatchVerification(){}
}
